function centile = compute_percentile(historicalData, exogenousVariable)
% compute_percentile Calculates the percentile rank of a value relative
%                     to a reference distribution.
%
%   centile = compute_percentile(historicalData, exogenousVariable)
%
%   INPUTS:
%       historicalData    - Vector containing reference values, such as
%                           modulation indices generated by permutation.
%       exogenousVariable - Observed value whose percentile rank is
%                           evaluated relative to historicalData.
%
%   OUTPUT:
%       centile           - Percentile rank of exogenousVariable, expressed
%                           as a percentage between 0 and 100.
%                           NaN is returned if exogenousVariable is NaN.
%
%   METHOD:
%       The percentile rank is calculated as the percentage of reference
%       values below the observed value, with ties contributing half
%       their weight:
%
%       centile = 100 * (nless + 0.5 * nequal) / N
%
%       where:
%           nless  - Number of reference values below the observed value.
%           nequal - Number of reference values equal to the observed value.
%           N      - Number of values in historicalData.
%
%   APPLICATION:
%       In a permutation analysis, this function compares an observed
%       statistic with its shuffled null distribution. The resulting
%       percentile rank describes the position of the observed statistic
%       within that distribution.

% Author - Grant W. Zempolich
% Created - 2024-04-16
% Last updated - 2026-10-13

% Return NaN when the observed value is undefined.
if isnan(exogenousVariable)
    centile = NaN;

else
    % Count reference values strictly below the observed value.
    nless = sum(historicalData < exogenousVariable);

    % Count reference values equal to the observed value.
    nequal = sum(historicalData == exogenousVariable);

    % Calculate percentile rank, assigning half weight to tied values.
    centile = 100 * (nless + 0.5 * nequal) / length(historicalData);
end

end